import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    doc = app.activeDocument

    mgr = adsk.cam.CAMManager.get()
    libMgr = mgr.libraryManager
    toolLibs = libMgr.toolLibraries
    localRoot = toolLibs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation)

    tiwURL = None
    for u in toolLibs.childAssetURLs(localRoot):
        if 'TIW' in u.toString():
            tiwURL = u
            break

    tiwLib = toolLibs.toolLibraryAtURL(tiwURL)

    # Dump all parameters for first 3 tools
    for i in range(min(3, tiwLib.count)):
        tool = tiwLib.item(i)
        print(f'\n=== Tool {i} ===')
        params = tool.parameters
        for j in range(params.count):
            p = params.item(j)
            try:
                val = p.value.value
            except:
                val = '?'
            try:
                expr = p.expression
            except:
                expr = '?'
            print(f'  [{j:3d}] {p.name:40s} = {val!r:20}  expr={expr!r}')

import adsk.core, adsk.fusion, adsk.cam

def run(_context):
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))

    setup = cam.setups.item(0)
    rough_op = setup.operations.item(0)
    print('Op name:', rough_op.name)

    # Find relevant parameters by scanning for key terms
    rp = rough_op.parameters

    keywords = ['step', 'load', 'stock', 'depth', 'optimal', 'radial', 'axial', 
                'spindle', 'feed', 'ramp', 'pocket', 'contour', 'tolerance']

    found = {}
    for i in range(rp.count):
        p = rp.item(i)
        nm = p.name.lower()
        for kw in keywords:
            if kw in nm:
                try:
                    val = p.value.value
                except:
                    val = '?'
                try:
                    expr = p.expression
                except:
                    expr = '?'
                found[p.name] = (val, expr)
                break

    for name, (val, expr) in sorted(found.items()):
        print(f'  {name:55} = {str(val):20}  expr={expr!r}')
